function graph(ac,out){let g=graphs.get(ac);if(g)return g;const drums=ac.createGain(),music=ac.createGain(),duck=ac.createGain(),send=ac.createGain(),delay=ac.createDelay(2),feedback=ac.createGain(),echoTone=ac.createBiquadFilter(),wet=ac.createGain(),reverb=ac.createConvolver(),room=ac.createGain();drums.gain.value=.82;music.gain.value=bare?0:Number($('#layers').value)/100;duck.gain.value=1;drums.connect(out);music.connect(duck);duck.connect(out);duck.connect(send);send.gain.value=.2;delay.delayTime.value=Math.min(1.8,60/bpm*.75);feedback.gain.value=.24;echoTone.type='lowpass';echoTone.frequency.value=2600;wet.gain.value=bare?0:profile[genre].echo;send.connect(delay);delay.connect(echoTone);echoTone.connect(feedback);feedback.connect(delay);echoTone.connect(wet);wet.connect(out);const length=Math.floor(ac.sampleRate*1.7),impulse=ac.createBuffer(2,length,ac.sampleRate);let seed=891;for(let c=0;c<2;c++){let d=impulse.getChannelData(c);for(let i=0;i<length;i++){seed=(seed*16807)%2147483647;d[i]=(seed/1073741823.5-1)*Math.pow(1-i/length,3)*.32}}reverb.buffer=impulse;room.gain.value=bare?0:profile[genre].verb;duck.connect(reverb);reverb.connect(room);room.connect(out);g={drums,music,duck,delay,wet,room};graphs.set(ac,g);return g;}
