function syncAIControls(){const busy=Boolean(aiController),ready=Boolean(aiConfig?.configured),signed=Boolean(aiConfig?.authenticated);$('#aiConnection').hidden=!useAI;$('#aiGenerate').disabled=!busy&&(!ready||!signed||!freeHits||freeHits.length<2);$('#aiGenerate').textContent=busy?'Cancel generation':aiBuffer?'Generate another version ↻':'3 / Generate music ↗';$('#aiSignIn').hidden=!useAI||!ready||signed;$('#play').disabled=useAI&&!aiBuffer;$('#play').textContent=playing?'■ Stop playback':useAI?(aiBuffer?'▶ Play AI + my rhythm':'Generate AI to play'):'▶ Play local synth';if(!useAI)return;if(!aiConfig)$('#aiStatus').textContent='Đang kiểm tra kết nối…';else if(aiConfig.connectionError)$('#aiStatus').textContent='Không kết nối được máy chủ tạo nhạc. Mở http://localhost:8000 rồi bấm Kết nối lại. Đây không phải thông báo thiếu API key.';else if(!ready)$('#aiStatus').textContent='Máy chủ chưa đọc được API key. Kiểm tra file .env trên máy.';else if(!signed)$('#aiStatus').textContent='Sign in to use AI music. Your club design stays public.';else if(aiLastError&&!busy)$('#aiStatus').textContent=aiLastError;else if(!busy&&!aiBuffer)$('#aiStatus').textContent='Tap a rhythm, finish it, then generate a full AI backing around your groove.';}
async function loadAIConfig(){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),5000);try{const response=await fetch(new URL('./api/music/config',import.meta.url),{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('Backend unavailable');const config=await response.json();if(typeof config.configured!=='boolean'||typeof config.authenticated!=='boolean')throw Error('Not the music backend');aiConfig=config;}catch{aiConfig={configured:false,authenticated:false,connectionError:true};}finally{clearTimeout(timeout);}syncAIControls();}

window.addEventListener('focus',()=>{if(!aiController)loadAIConfig();});
setInterval(()=>{if(!document.hidden&&!aiController&&!aiConfig?.configured)loadAIConfig();},5000);
function cancelAI(){if(aiController){aiSerial++;aiController.abort();aiController=null;$('#aiStatus').textContent='Generation canceled.';syncAIControls();}}
async function generateAI(){if(aiController){cancelAI();return;}if(!aiConfig?.configured||!aiConfig?.authenticated){syncAIControls();return;}if(playing)stop();audio();await ctx.resume();let tempo=Math.round(bpm);if(tempo<60||tempo>200){$('#aiStatus').textContent='Choose a tempo between 60 and 200 BPM for AI music.';return;}bpm=tempo;$('#bpm').value=bpm;const serial=++aiSerial,controller=new AbortController();aiController=controller;aiBuffer=null;aiLastError=null;syncAIControls();$('#aiStatus').textContent='Connecting to Google Lyria…';try{const result=await requestAIMusic({genre,bpm,hits:freeHits,loopBars:freeLoopBars,density:.65,brightness:.45},{signal:controller.signal,onProgress:event=>{if(serial===aiSerial)$('#aiStatus').textContent=event.message||'Composing…';}});if(serial!==aiSerial)return;aiBuffer=pcmToBuffer(ctx,result);aiBufferGenre=genre;$('#aiStatus').textContent='AI backing ready · Google Lyria · '+result.meta.seconds.toFixed(1)+' seconds · layered AI backing + your tapped rhythm.';master.gain.setValueAtTime(Number($('#volume').value)/100*.8,ctx.currentTime);await start();$('#notice').textContent='Your tapped rhythm + AI bass, harmony and textures. Lights follow the actual sound.';}catch(e){if(serial!==aiSerial)return;aiBuffer=null;aiLastError=e.name==='AbortError'?'Generation canceled.':e.message;$('#aiStatus').textContent=aiLastError;$('#notice').textContent='AI did not generate audio. No synth preset was substituted.';}finally{if(serial===aiSerial){aiController=null;syncAIControls();}}}
$('#aiGenerate').onclick=generateAI;$('#engine').onchange=()=>{cancelAI();if(playing)stop();useAI=$('#engine').value==='ai';syncAIControls();$('#notice').textContent=useAI?'AI music uses Google Lyria; generation requires the creator’s provider connection.':'Local synth preview selected. This audio is not AI-generated.';};document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!aiController)loadAIConfig()});window.addEventListener('pagehide',()=>{cancelAI();try{aiSource?.stop()}catch{}});loadAIConfig();

